data.minimal_example:
final control = HandSignatureControl(
  initialSetup: CubicPathSetup(
      threshold: 3.0,
      smoothRatio: 0.65,
      velocityRange: 2.0,
      pressureRatio: 0.0,
      args: {'color': 'red'}
  ),
);

final widget = HandSignature(
  control: control,
  drawer: ShapeSignatureDrawer(
    color: Colors.blueGrey,
    width: 1.0,
    maxWidth: 10.0,
  ),
);
